414	 * How it was cut short, in the words for the person reading the comment.
415	 *
416	 * `runtime` and `iterations` are one ending to `turn.ts` — the decisions below it
417	 * turn on the same answer for either — and two different sentences here, which is
418	 * why the core's own word travels this far rather than a boolean.
419	 *
420	 * This said "ran out of iterations" for both, and the runner passes
421	 * `--max-runtime-secs` and no `--max-iterations`. So the ceiling it hits is always
422	 * the clock, and that sentence was always the wrong one.
423	 *
424	 * `context_limit` is the fourth ceiling and gets its own sentence rather than being
425	 * folded into "ran out of time": the window filled, and the way out -- a larger
426	 * `context_limit`, or a smaller task -- is different from waiting less.
427	 */
428	function howItWasCutShort(endedBecause: string | undefined): string {
429	  if (endedBecause === "stopped") return "was stopped";
430	  if (endedBecause === "loop") return "got stuck repeating itself";
431	  if (endedBecause === "failed") return "did not finish";
432	  if (endedBecause === "context_limit") return "ran out of context";
433	  return endedBecause === "iterations" ? "ran out of iterations" : "ran out of time";
434	}
