745	/**
746	 * The footer, as one block — the only place its pieces are assembled.
747	 *
748	 * Two kinds of comment carry it. The result comment this file posts when the
749	 * model returned prose, and — through `appendFooter` — the comment a
750	 * session-ending tool posted instead, which used to end the run with no footer
751	 * and whose tokens the metrics report (`token-line.ts`) then never counted. The
752	 * footer is about ONE run, so it goes on the ONE comment that ended that run's
753	 * turn, whichever of the two that was.
754	 *
755	 * The report link is to the branch tip rather than to a commit, because the
756	 * report is written after this comment is posted — which is what somebody
757	 * following it wants anyway: the current state, including this run. A permalink
758	 * would show the metrics as they were a moment before.
759	 *
760	 * Omitted rather than guessed when the repository is unknown, because a broken
761	 * link in every comment is worse than no link at all.
762	 */
763	export function buildFooter(args: {
764	  agent: string;
765	  runUrl: string;
766	  repo?: string;
767	  /** The token line, as the run's log gave it up. Absent when the log carried no usage. */
768	  tokenLine?: string;
769	  /**
770	   * What the tools did to this run, counted from its session by `tool-trouble.ts`.
771	   * Absent when there was none, which is the ordinary run.
772	   */
773	  toolTrouble?: string;
774	  /** How the run ended, for the cut-short notices. Empty in the appended footer. */
775	  endedBecause?: string;
776	  /** What a run that hit a limit spent its budget on, from `tool-tally.ts`. */
777	  spentOn?: string;
778	}): string {
779	  const lines: string[] = ["---"];
780	  if (args.tokenLine !== undefined) lines.push(args.tokenLine);
781	  const metrics = args.repo
782	    ? ` · [metrics](https://github.com/${args.repo}/blob/atomaton-data/metrics/report.md)`
783	    : "";
784	  lines.push(`_run by [${args.agent}](${args.runUrl})${metrics}_`);
785	  // Under the run link and above the notice saying how to continue: this is a fact
786	  // about the run, the notice is the action, and the action reads last.
787	  //
788	  // No `⚠️`, in the same voice as the token line and the run link above it. The
789	  // marker means one thing in this footer -- the run was cut off and a person has to
790	  // continue it -- and this line is not that. Most of what it counts is a guard doing
791	  // its job, which `looksRefused` exists to distinguish from a tool breaking;
792	  // measured, 107 of 396 runs carried a refused or errored call, so a warning sign
793	  // here would appear on a quarter of all comments and the one below it would stop
794	  // being read. The line's job is to make the count impossible to lose, not to claim
795	  // a fault.
796	  if (args.toolTrouble !== undefined) lines.push(`_${args.toolTrouble}_`);
797	  if (args.endedBecause === "stopped") {
798	    // Says the session survived, because that is the whole difference between this
799	    // and cancelling the job, and the person who stopped it cannot tell from here
800	    // which one they got.
801	    lines.push(
802	      `⏸️ _Stopped on request. **The session is saved.** Comment \`/resume\` to continue ` +
803	        `from here, or \`/${args.agent}\` with an instruction on the following lines._`,
804	    );
805	  } else if (reachedLimit(args.endedBecause)) {
806	    // The limits only. A failed run's footer would repeat what the failure notice above
807	    // it already says -- that it did not finish, and how to continue.
808	    lines.push(`⚠️ _The run ${howItWasCutShort(args.endedBecause)}. Comment \`/${args.agent}\` to continue._`);
809	  }
810	  // Under the line that says what to do, because it is the fact that decides
811	  // whether that is the right thing to do — see `tool-tally.ts`.
812	  if (args.spentOn !== undefined) lines.push(`_${args.spentOn}_`);
813	
814	  return lines.join("\n");
815	}
816	
817	/**
818	 * Append the footer onto the comment a session-ending tool posted, in place.
819	 *
820	 * A tool that ends the session (`create_pr`, `launch_sub_agent`,
821	 * `request_close_issue`, `reload_environment`) posts its own turn-ending comment
822	 * and records it (`ending-comment.ts`, in the run's own directory). This reads it
823	 * back and PATCHes the footer onto it, so the run's tokens reach the metrics
824	 * report — which counts token lines off comment bodies — and a person reading the
825	 * thread sees the same run facts they would under any result comment.
826	 *
827	 * Reading the body back rather than recording it at post time: the file carries an
828	 * id, which is the only fact still true hours later. A body read fresh is the
829	 * body that is really there, whatever touched the comment in between.
830	 */
831	function appendFooter(args: {
832	  repo: string;
833	  commentId: string;
834	  agent: string;
835	  runUrl: string;
836	  tokenLine?: string;
837	  toolTrouble?: string;
838	}): void {
839	  const current = gh(
840	    "api",
841	    `repos/${args.repo}/issues/comments/${args.commentId}`,
842	    "--jq",
843	    ".body",
844	  );
845	  if (current.code !== 0 || !current.stdout.trim()) {
846	    console.error(
847	      `could not read the ending comment ${args.commentId}: ` +
848	        `${current.stderr || current.stdout || "(empty body)"} -- the footer is not appended`,
849	    );
850	    return;
851	  }
852	  const body = `${current.stdout.trim()}\n\n${buildFooter({
853	    agent: args.agent,
854	    runUrl: args.runUrl,
855	    repo: args.repo,
856	    tokenLine: args.tokenLine,
857	    toolTrouble: args.toolTrouble,
858	  })}`;
859	  const updated = gh(
860	    "api",
861	    `repos/${args.repo}/issues/comments/${args.commentId}`,
862	    "--method",
863	    "PATCH",
864	    "-f",
865	    `body=${body}`,
866	  );
867	  if (updated.code !== 0) {
868	    console.error(`could not append the footer: ${updated.stderr || updated.stdout}`);
869	    return;
870	  }
871	  console.error(`footer appended to the ending comment ${args.commentId}`);
872	}
873	
