883	 * failure and the flag was never written, which is the conservative direction.
884	 */
885	function colourForStepFailure(stepFailed: boolean, atomaFailed: boolean): void {
886	  if (!stepFailed || atomaFailed) return;
887	  console.error("The machinery failed, not the agent; the notice healed the thread, but the run stays red.");
888	  process.exitCode = 1;
